const b = $input.first().json.body ?? $input.first().json;
return [{
  json: {
    messageId: String(b.message_id || 'msg-unknown'),
    from: String(b.from || ''),
    subject: String(b.subject || '(Kein Betreff)'),
    snippet: String(b.text || b.snippet || '').slice(0, 2000),
    llmUrl: String(b.llm_url || 'http://ollama:11434/v1/chat/completions'),
    model: String(b.model || 'conrad-n8n-agent:4b'),
    markAsRead: false
  }
}];

const resp = $input.first().json;
const src = $('Normalize & Unread-Lock').first().json;
const fallbackOut = {
  messageId: src.messageId,
  markAsRead: false,
  draftOnly: true,
  kategorie: 'Sonstiges',
  prioritaet: 'mittel',
  aktion: 'manuell_pruefen',
  label: 'KI/Pruefen',
  antwort_entwurf_betreff: '',
  antwort_entwurf_text: '',
  parseOk: false
};
if (resp.error) return [{ json: { ...fallbackOut, error: String(resp.error.message || resp.error) } }];
let raw = String(resp?.choices?.[0]?.message?.content ?? '').trim();
raw = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
const m = raw.match(/\{[\s\S]*\}/);
const candidate = m ? m[0] : raw;
try {
  const d = JSON.parse(candidate);
  const validKat = new Set(['Rechnung','Kundenanfrage','Termin','Newsletter','Spam','Sonstiges']);
  const validAkt = new Set(['entwurf_erstellen','nur_labeln','manuell_pruefen']);
  return [{
    json: {
      messageId: src.messageId,
      markAsRead: false,
      draftOnly: true,
      kategorie: validKat.has(d.kategorie) ? d.kategorie : 'Sonstiges',
      prioritaet: ['hoch','mittel','niedrig'].includes(d.prioritaet) ? d.prioritaet : 'mittel',
      aktion: validAkt.has(d.aktion) ? d.aktion : 'manuell_pruefen',
      label: String(d.label || d.kategorie || 'Sonstiges'),
      antwort_entwurf_betreff: String(d.antwort_entwurf_betreff || ''),
      antwort_entwurf_text: String(d.antwort_entwurf_text || ''),
      parseOk: true
    }
  }];
} catch (e) {
  return [{ json: { ...fallbackOut, rawPreview: raw.slice(0, 120) } }];
}
